      --color-muted-text: #b8c2d9;
      --color-border: #31415f;
      --color-link: #8cc8ff;
      --color-focus: #8cc8ff;
      --color-accent: #7dd3fc;
      --color-danger: #ff8f8f;
      --shadow-panel: 0 24px 60px rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, #1b2845 0, transparent 45%),
        linear-gradient(180deg, #08101f 0%, #0b1020 100%);
      color: var(--color-text);
      display: grid;
      place-items: center;
      padding: 24px;
    }

    main {
      width: min(100%, 460px);
    }

    .card {
      background: linear-gradient(180deg, var(--color-panel) 0%, var(--color-panel-2) 100%);
      border: 1px solid var(--color-border);
      border-radius: 20px;
      padding: 32px;
      box-shadow: var(--shadow-panel);
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.75rem, 3vw, 2.25rem);
      line-height: 1.15;
    }

    .intro {
      margin: 0 0 24px;
      color: var(--color-muted-text);
      line-height: 1.5;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      display: grid;
      gap: 10px;
    }

    .checkbox-row {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 12px;
      align-items: start;
      padding: 16px;
      border: 1px solid var(--color-border);
      border-radius: 14px;
      background: rgba(255, 255, 255, 0.02);
    }

    input[type="checkbox"] {
      inline-size: 1.2rem;
      block-size: 1.2rem;
      margin: 0.15rem 0 0;
      accent-color: var(--color-accent);
    }

    label {
      font-weight: 600;
      line-height: 1.5;
    }

    .required-mark {
      color: var(--color-accent);
      font-weight: 700;
    }

    .helper-text,
    .error-text,
    .status-text {
      margin: 0;
      font-size: 0.95rem;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--color-muted-text);
    }

    .error-text {
      color: var(--color-danger);
    }

    .status-text {
      color: var(--color-text);
      min-height: 1.5em;
    }

    button {
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.9rem 1.25rem;
      font: inherit;
      font-weight: 700;
      color: #08101f;
      background: linear-gradient(135deg, #8cc8ff 0%, #7dd3fc 100%);
      cursor: pointer;
      transition: transform 120ms ease, filter 120ms ease;
    }

    button:hover {
      filter: brightness(1.05);
    }

    button:active {
      transform: translateY(1px);
    }

    a {
      color: var(--color-link);
    }

    :focus-visible {
      outline: 3px solid var(--color-focus);
      outline-offset: 3px;
    }

    @media (max-width: 480px) {
      .card {
        padding: 24px;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
      }

      .card,
      .checkbox-row {
        background: Canvas;
        border-color: ButtonBorder;
        box-shadow: none;
      }

      button {
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonBorder;
      }

      a {
        color: LinkText;
      }

      :focus-visible {
        outline-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <div id="root"></div>
  <script>
    const createApp = () => `
      <main>
        <section class="card" aria-labelledby="page-title">
          <h1 id="page-title">Terms consent</h1>
          <p class="intro">Review the consent choice below, then confirm to continue.</p>
          ${ConsentForm()}
        </section>
      </main>
    `;

    const ConsentField = () => `
      <div class="form-field">
        <div class="checkbox-row">
          <input
            id="agree-terms"
            name="agreeTerms"
            type="checkbox"
            required
            aria-describedby="agree-help agree-error"
          >
          <label for="agree-terms">
            I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
          </label>
        </div>
        <p id="agree-help" class="helper-text">Required to submit this form.</p>
        <p id="agree-error" class="error-text" hidden>Error: You must agree before submitting.</p>
      </div>
    `;

    const SubmitButton = () => `
      <button type="submit">Submit consent</button>
    `;

    const ConsentForm = () => `
      <form id="consent-form" novalidate>
        ${ConsentField()}
        ${SubmitButton()}
        <p id="form-status" class="status-text" aria-live="polite"></p>
      </form>
    `;

    document.getElementById("root").innerHTML = createApp();

    const form = document.getElementById("consent-form");
    const checkbox = document.getElementById("agree-terms");
    const errorText = document.getElementById("agree-error");
    const statusText = document.getElementById("form-status");

    const showCheckboxError = () => {
      checkbox.setAttribute("aria-invalid", "true");
      errorText.hidden = false;
    };

    const clearCheckboxError = () => {
      checkbox.removeAttribute("aria-invalid");
      errorText.hidden = true;
    };

    checkbox.addEventListener("change", () => {
      if (checkbox.checked) {
        clearCheckboxError();
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!checkbox.checked) {
        statusText.textContent = "";
        showCheckboxError();
        checkbox.focus();
        return;
      }

      clearCheckboxError();
      statusText.textContent = "Consent submitted.";
    });
  </script>
</body>
</html>
